import{_ as s,l as i,o as e,c as n,v as t,p as l,x as r,d,i as c,S as h}from"./chunks/framework.InCnrqk-.js";const B=JSON.parse('{"title":"属性文法","description":"","frontmatter":{"title":"属性文法","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/attribute-grammar.md","filePath":"cs/attribute-grammar.md","lastUpdated":1789023840000}'),p={name:"cs/attribute-grammar.md"};function E(m,a,u,_,f,A){const o=i("Mermaid");return e(),n("div",null,[a[1]||(a[1]=t('<h1 id="属性文法" tabindex="-1">属性文法 <a class="header-anchor" href="#属性文法" aria-label="Permalink to &quot;属性文法&quot;">​</a></h1><div class="epigraph"><p>产生式上挂综合与继承属性；依赖图无环则可求值。语法给树，属性给树上传值。</p><footer>—— 据 Knuth, Semantics of Context-Free Languages, 1968；龙书第 5 章整理</footer></div><p>上一课<a href="/cs/incremental-parsing">增量解析</a>交出带区间的树。主干<a href="/cs/ast">抽象语法树</a>与<a href="/cs/ast-visitor">访问者</a>已能走遍。缺口是<strong>声明式的节点值</strong>：类型、作用域、代码地址不必全部写成手写遍的副作用。属性文法把「孩子综合出父、父继承给子」钉成规则。本课不把整个编译器改写成 AG 工具。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>访问者遍数一多，求值顺序隐在调用图里。Knuth：每个产生式一组属性方程。综合属性（S 属性）自底向上，正好可在 LR 归约时算——yacc 的 <code>$$=$1+$3</code> 就是。继承属性自上而下或从左兄到右弟，LL 更顺。缺口是<strong>依赖与可求值性</strong>，不是再定义 CFG。</p><p>循环依赖（类型与重载纠缠成环）使 AG 无法静态排程。实际编译器用手写遍或约束求解，AG 是说明书。</p><h3 id="继承不是面向对象的-extends" tabindex="-1">继承不是面向对象的 extends <a class="header-anchor" href="#继承不是面向对象的-extends" aria-label="Permalink to &quot;继承不是面向对象的 extends&quot;">​</a></h3><p>这里的 inherited attribute 是「从树的上下文流进节点的值」，如外围作用域、期望类型。不要和类继承混名。</p><p><span class="marginnote">Knuth 1968。龙书第 5 章：S 属性、L 属性。本课不引入 AG 的全部子类谱系作业。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>为 <code>E → E + T</code> 写：<code>E.val = E1.val + T.val</code>（综合）。为声明列表写：<code>D2.env = D1.env ∪ {名字}</code>（继承给后续）。画依赖图，拓扑求值；或限制为 L 属性，保证一次左到右遍历足够。</p>',11)),(e(),l(h,null,{default:r(()=>[c(o,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20TREE%5B%22%E5%88%86%E6%9E%90%E6%A0%91%22%5D%20--%3E%20S%5B%22%E7%BB%BC%E5%90%88%20%E2%86%91%22%5D%0A%20%20TREE%20--%3E%20I%5B%22%E7%BB%A7%E6%89%BF%20%E2%86%93%22%5D%0A%20%20S%20--%3E%20EQ%5B%22%E5%B1%9E%E6%80%A7%E6%96%B9%E7%A8%8B%22%5D%0A%20%20I%20--%3E%20EQ%0A%20%20EQ%20--%3E%20VAL%5B%22%E8%8A%82%E7%82%B9%E5%80%BC%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>与符号表：<a href="/cs/scope-symtab">作用域</a> 可以是继承下来的环境指针，综合出的是绑定。后课语法制导翻译把方程写成生成 IR 的动作。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>S 属性 ⊂ L 属性 ⊂ 无环 AG。yacc 擅长 S 属性；要继承时人或用全局栈模拟环境，或换遍。增量：属性依赖跨脏区时要重求值，比纯树复用更脏——接上一课的边界。</p><p>不要用 AG 表达非上下文无关的全部 C++ 规则；可表达的是「树已定时的函数」。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写 Knuth 的全部算法复杂度证明。不把属性当运行时反射。后课默认：S 属性可在归约时求；更一般用多遍。下一课：语法制导翻译——把属性方程落成「生成三地址」的动作。</p><p>类型系统进阶课会把「值」换成判断过程，不是方程工具的失败。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>属性文法：产生式上的综合/继承方程。</li><li>S 属性对齐 LR 动作；L 属性对齐一次左到右。</li><li>环状依赖就换约束或手写遍。</li><li>出处：Knuth, 1968；Aho et al., 龙书第 5 章。</li></ul>',9))])}const S=s(p,[["render",E]]);export{B as __pageData,S as default};
